package edu.smartlibrary.api;
import edu.smartlibrary.api.ApiModels.*;import edu.smartlibrary.model.*;import edu.smartlibrary.repo.UserRepository;import edu.smartlibrary.security.TokenService;import edu.smartlibrary.service.LibraryService;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.Locale;
@RestController @RequestMapping("/api/auth") public class AuthController{
 private final UserRepository users;private final PasswordEncoder passwords;private final TokenService tokens;private final LibraryService service;
 @Value("${app.librarian.setup-key:}") private String setupKey;
 public AuthController(UserRepository u,PasswordEncoder p,TokenService t,LibraryService s){users=u;passwords=p;tokens=t;service=s;}
 @PostMapping("/register") public ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account already uses this email.");Role role=r.role();if(role==null)role=r.setupKey()!=null&&!r.setupKey().isBlank()?Role.LIBRARIAN:Role.STUDENT;if(role==Role.LIBRARIAN&&(r.setupKey()==null||setupKey.isBlank()||!setupKey.equals(r.setupKey())||users.countByRole(Role.LIBRARIAN)>0))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Librarian setup key is invalid or initial setup is already complete.");if(role!=Role.STUDENT&&role!=Role.LIBRARIAN)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose Student or Librarian as the account type.");AppUser u=users.save(new AppUser(r.name().trim(),r.email().trim().toLowerCase(Locale.ROOT),passwords.encode(r.password()),role));return ResponseEntity.status(HttpStatus.CREATED).body(new AuthResponse(tokens.create(u),service.userView(u)));}
 @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){AppUser u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect."));if(!passwords.matches(r.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect.");return new AuthResponse(tokens.create(u),service.userView(u));}
 @PostMapping("/logout") public ResponseEntity<Void> logout(){return ResponseEntity.noContent().build();}
}
